from dataclasses import dataclass, field
from typing import Optional, Dict, Any, List

@dataclass
class SynthesisInput:
    text: Optional[str] = None
    ssml: Optional[str] = None

@dataclass
class VoiceSelectionParams:
    language_code: str
    name: Optional[str] = None
    ssml_gender: Optional[str] = None
    natural_voice_profile: Optional[str] = None

@dataclass
class AudioConfig:
    audio_encoding: str = "MP3"
    speaking_rate: Optional[float] = None
    pitch: Optional[float] = None
    volume_gain_db: Optional[float] = None
    sample_rate_hertz: Optional[int] = None
    effects_profile_id: Optional[List[str]] = field(default_factory=list)

@dataclass
class SynthesizeSpeechRequest:
    input: SynthesisInput
    voice: VoiceSelectionParams
    audio_config: AudioConfig

@dataclass
class SynthesizeSpeechResponse:
    audio_content: bytes
    content_type: str = "audio/mpeg"

@dataclass
class Voice:
    name: str
    language_codes: List[str]
    ssml_gender: str
    natural_voice_profile: Optional[str] = None
    custom_voice_type: Optional[str] = None
    custom_voice_data_ready: Optional[bool] = None

@dataclass
class ListVoicesResponse:
    voices: List[Voice]

from speech_client import get_text_to_speech_client
from speech_models import Voice, ListVoicesResponse
from google.cloud import texttospeech

def list_voices(language_code: str = None) -> ListVoicesResponse:
    client = get_text_to_speech_client()
    voices = client.list_voices(language_code=language_code).voices

    voice_list = []
    for voice in voices:
        voice_list.append(Voice(
            name=voice.name,
            language_codes=list(voice.language_codes),
            ssml_gender=texttospeech.SsmlVoiceGender(voice.ssml_gender).name,
            natural_voice_profile=voice.natural_voice_profile
        ))
    return ListVoicesResponse(voices=voice_list)

def select_voice_by_name(voice_name: str, language_code: str = None) -> Voice:
    all_voices = list_voices(language_code=language_code).voices
    for voice in all_voices:
        if voice.name == voice_name:
            return voice
    return None

def select_voice_by_gender(language_code: str, ssml_gender: str) -> Voice:
    all_voices = list_voices(language_code=language_code).voices
    for voice in all_voices:
        if voice.ssml_gender == ssml_gender.upper():
            return voice
    return None

import os

def save_audio_to_file(audio_bytes: bytes, file_path: str):
    try:
        with open(file_path, "wb") as out_file:
            out_file.write(audio_bytes)
        return {"status": "success", "file_path": file_path}
    except Exception as e:
        return {"status": "error", "message": str(e)}

from google.cloud import language_v1
import os

def analyze_safety_content(text_content: str) -> dict:
    client = language_v1.LanguageServiceClient()

    document = language_v1.Document(content=text_content, type_=language_v1.Document.Type.PLAIN_TEXT)

    # Available categories: https://cloud.google.com/natural-language/docs/reference/rest/v1/ClassificationCategory
    response = client.classify_text(request={'document': document})

    # For simplicity, we'll return a dictionary of categories and their confidence scores
    # In a real application, you might define specific safety thresholds and actions
    safety_analysis = {
        "categories": [
            {"name": category.name, "confidence": category.confidence}
            for category in response.categories
        ]
    }
    return safety_analysis
